using static Bootcamp.Check;
using System.Security.Claims;

// The shared part: who is asking, does the invoice exist, and is it in their tenant?
(int Status, Invoice? Invoice) LoadForUser(ClaimsPrincipal user, int id, Func<int, Invoice?> load)
{
    if (user.Identity?.IsAuthenticated != true) return (401, null);
    var invoice = load(id);
    if (invoice is null || invoice.TenantId != user.FindFirst("tenant")?.Value) return (404, null);
    return (200, invoice);
}

(int Status, Invoice? Body) GetInvoice(ClaimsPrincipal user, int id, Func<int, Invoice?> load) =>
    LoadForUser(user, id, load);

(int Status, Invoice? Body) Approve(ClaimsPrincipal user, int id, Func<int, Invoice?> load, Action<Invoice> save)
{
    var (status, invoice) = LoadForUser(user, id, load);
    if (invoice is null) return (status, null);
    var self = invoice.CreatedBy == user.FindFirst(ClaimTypes.NameIdentifier)?.Value;
    if (!user.IsInRole("approver") || self) return (403, null);
    var approved = invoice with { Status = "approved" };
